    docs=[d for d in s.current_records() if d['state']=='active' and d['tenant']==vs.tenant and d['acl_group'] in vs.groups]
    if not docs or not tokens(q): return []
    T={d['id']:Counter(tokens(d['title']+' '+d['body'])) for d in docs}
    L={i:sum(c.values()) for i,c in T.items()}; n=len(docs); avg=sum(L.values())/n
